#include "os.h"
/* Installer: schreibt Violyx auf eine ganze Platte. Alle Dialoge stehen vorab auf Nein;
   geschrieben wird erst nach Auswahl, Ja und eingetipptem Wort LOESCHEN. */
typedef struct { char name[8],pad[8]; } un;
static const u8*img; static u64 imglen;
void install_set_image(const void*p,u64 n){ img=p; imglen=n; }
int install_available(void){ return img&&imglen>24&&!memcmp(img,"VIOINST1",8); }
static u32 crc32(const u8*p,size_t n){ u32 c=~0u; while(n--){ c^=*p++; for(int i=0;i<8;i++)c=(c>>1)^(0xEDB88320u&-(c&1)); } return ~c; }
static u64 need_sectors(void){ return *(u64*)(img+8); }
static void describe(blkdev*d,char*o,int n,int*foreign){ static u8 s[512]; *foreign=1; if(d->rd(d,0,s)){ strlcpy_(o,TR("nicht lesbar","not readable"),n); return; } int zero=1; for(int i=0;i<512;i++) if(s[i]){ zero=0; break; } int mbr=s[510]==0x55&&s[511]==0xAA; int types=0; for(int i=0;i<4;i++) if(s[446+i*16+4])types++;
  u8 h[512]; int gpt=!d->rd(d,1,h)&&!memcmp(h,"EFI PART",8); if(gpt){ u64 el=*(u64*)(h+72); u32 cnt=*(u32*)(h+80),esz=*(u32*)(h+84); int parts=0,win=0,vio=0; if(esz>=128&&esz<=512&&cnt<=256){ for(u32 i=0;i<cnt;i++){ if(d->rd(d,el+i*esz/512,s))break; u8*e=s+(i*esz)%512; int used=0; for(int k=0;k<16;k++) if(e[k])used=1; if(!used)continue; parts++; if(!memcmp(e,"VIOLYXFSPARTITN1",16))vio=1; if(e[0]==0xA2&&e[1]==0xA0&&e[2]==0xD0&&e[3]==0xEB)win=1; if(e[0]==0x16&&e[1]==0xE3&&e[2]==0xC9&&e[3]==0xE3)win=1; } } ksnprintf(o,n,TR("%s %d Partition(en)%s","%s %d partition(s)%s"),vio?"Violyx,":"GPT,",parts,win?TR(", WINDOWS MÖGLICH",", MAY CONTAIN WINDOWS"):""); return; }
  if(mbr&&types){ ksnprintf(o,n,TR("MBR, %d Partition(en), enthält Daten","MBR, %d partition(s), contains data"),types); return; } if(zero&&!mbr){ for(int k=2;k<64;k++){ if(d->rd(d,k*2048,s))break; for(int i=0;i<512;i++) if(s[i]){ strlcpy_(o,TR("keine Tabelle, aber Daten","no table, but contains data"),n); return; } } *foreign=0; strlcpy_(o,TR("sieht leer aus","looks empty"),n); return; } strlcpy_(o,TR("unbekannter Inhalt","unknown content"),n); }
static void sizestr(u64 sec,char*o,int n){ u64 mb=sec/2048; if(mb>=2048)ksnprintf(o,n,"%ld GB",mb/1024); else ksnprintf(o,n,"%ld MB",mb); }
static int choose_disk(void){ int n=blk_count(),s=0; char t[100]; int fo; for(;;){ int x,y; dlg_box(TR("Violyx installieren: Platte wählen","Install Violyx: choose disk"),70,n*2+7,&x,&y); text(x+3,y+2,AT(C_RAISE,C_LAV),TR("Violyx wird immer auf die GESAMTE Platte installiert.","Violyx is always installed on the ENTIRE disk.")); for(int i=0;i<n;i++){ blkdev*d=blk_get(i); char z[16],c[60]; sizestr(d->sectors,z,16); describe(d,c,60,&fo); int bad=d==fs_device()||d->sectors<need_sectors(); ksnprintf(t,100," %s %s: %s",d->name,z,d->model[0]?d->model:TR("unbekanntes Modell","unknown model")); u8 a=i==s?AT(C_SEL,C_GLOW):bad?AT(C_RAISE,C_DIM):AT(C_RAISE,C_LAV); fill(x+2,y+4+i*2,66,2,' ',a); text(x+2,y+4+i*2,a,t); ksnprintf(t,100,"   %s",d==fs_device()?TR("Enthält die aktiven Violyx-Daten, nicht wählbar","Holds the active Violyx data, not selectable"):d->sectors<need_sectors()?TR("zu klein","too small"):c); text(x+2,y+5+i*2,a,t); } text(x+3,y+n*2+5,AT(C_RAISE,C_LAV),TR("Pfeile wählen   Enter weiter   Esc abbrechen","Arrows select   Enter continue   Esc cancel")); ui_show();
    key_t k=key_wait(); if(k.key==K_ESC)return -1; if(k.key==K_UP&&s)s--; else if(k.key==K_DOWN&&s<n-1)s++; else if(k.key==K_ENTER){ blkdev*d=blk_get(s); if(d==fs_device()||d->sectors<need_sectors())continue; return s; } } }
/* Warnung: Vorauswahl Nein, Enter bricht ab, solange nicht aktiv auf Ja gewechselt wurde */
static int warn(blkdev*d){ int yes=0; char t[100],z[16],c[60]; int fo; sizestr(d->sectors,z,16); describe(d,c,60,&fo); for(;;){ int x,y; dlg_box(TR("ACHTUNG","WARNING"),70,15,&x,&y); u8 h=AT(C_HOT,C_VOID); fill(x+2,y+2,66,3,' ',h); text(x+4,y+2,h,TR("ALLE DATEN AUF DIESER PLATTE WERDEN","ALL DATA ON THIS DISK WILL BE")); text(x+4,y+3,h,TR("UNWIDERRUFLICH GELÖSCHT.","PERMANENTLY ERASED.")); text(x+4,y+4,h,TR("Sämtliche Partitionen gehen verloren!","All partitions will be lost!")); ksnprintf(t,100,TR("Platte:  %s, %s","Disk:    %s, %s"),d->name,z); text(x+3,y+6,AT(C_RAISE,C_LAV),t); ksnprintf(t,100,TR("Modell:  %s","Model:   %s"),d->model[0]?d->model:TR("unbekannt","unknown")); text(x+3,y+7,AT(C_RAISE,C_LAV),t); ksnprintf(t,100,TR("Inhalt:  %s","Content: %s"),c); text(x+3,y+8,AT(C_RAISE,C_LAV),t); text(x+3,y+10,AT(C_RAISE,C_GLOW),TR("Wirklich fortfahren?","Really continue?")); text(x+24,y+12,yes?AT(C_RAISE,C_LAV):AT(C_SEL,C_GLOW),TR("  Nein  ","  No  ")); text(x+36,y+12,yes?AT(C_HOT,C_VOID):AT(C_RAISE,C_LAV),TR("  Ja  ","  Yes  ")); ui_show(); key_t k=key_wait(); if(k.key==K_ESC||k.key=='n'||k.key=='N')return 0; if(k.key==K_LEFT)yes=0; else if(k.key==K_RIGHT)yes=1; else if(k.key==K_ENTER)return yes; } }
static void bar(int x,int y,u64 a,u64 b,const char*t){ dlg_box(TR("Violyx installieren","Install Violyx"),60,8,&x,&y); text(x+3,y+2,AT(C_RAISE,C_LAV),t); int w=(int)(b?a*52/b:0); fill(x+3,y+4,54,1,0xB0,AT(C_VOID,C_DIM)); fill(x+3,y+4,w,1,0xDB,AT(C_VOID,C_NEON)); text(x+3,y+6,AT(C_RAISE,C_LAV),TR("Bitte nicht ausschalten.","Please do not turn off.")); ui_show(); }
static int fixgpt(blkdev*d){ static u8 h[512],s[512]; u64 tot=d->sectors; if(d->rd(d,0,s))return -1; u64 v=tot-1>0xFFFFFFFFu?0xFFFFFFFFu:tot-1; for(int i=0;i<4;i++) if(s[446+i*16+4]==0xEE)*(u32*)(s+446+i*16+12)=(u32)v; if(d->wr(d,0,s))return -1; if(d->rd(d,1,h)||memcmp(h,"EFI PART",8))return -1; u64 el=*(u64*)(h+72); u32 cnt=*(u32*)(h+80),esz=*(u32*)(h+84); u32 secs=(cnt*esz+511)/512; if(secs>128)return -1; u64 bk=tot-1-secs;
  for(u32 i=0;i<secs;i++){ if(d->rd(d,el+i,s)||d->wr(d,bk+i,s))return -1; } *(u64*)(h+32)=tot-1; *(u64*)(h+48)=tot-secs-2; *(u32*)(h+16)=0; *(u32*)(h+16)=crc32(h,92); if(d->wr(d,1,h))return -1; *(u64*)(h+24)=tot-1; *(u64*)(h+32)=1; *(u64*)(h+72)=bk; *(u32*)(h+16)=0; *(u32*)(h+16)=crc32(h,92); if(d->wr(d,tot-1,h))return -1; return d->fl(d); }
static int write_all(blkdev*d){ u32 nrec=*(u32*)(img+16); const u8*rec=img+24; const u8*data=rec+nrec*16; u64 total=0,done=0; for(u32 i=0;i<nrec;i++)total+=*(u32*)(rec+i*16+8); static u8 z[512],s[512]; memset(z,0,512); int x=0,y=0; const u8*p=data; if((u64)(data-img)>imglen)return -1;
  /* alte Partitionstabelle am Plattenende ungueltig machen */ for(int i=1;i<=33;i++) if(d->wr(d,d->sectors-i,z))return -1;
  for(u32 i=0;i<nrec;i++){ u64 l=*(u64*)(rec+i*16); u32 c=*(u32*)(rec+i*16+8),k=*(u32*)(rec+i*16+12); if(k){ if((u64)(p+c*512ull-img)>imglen)return -1; } for(u32 j=0;j<c;j++){ if(k){ memcpy(s,p,512); p+=512; if(d->wr(d,l+j,s))return -1; } else if(d->wr(d,l+j,z))return -1; if(!(++done%256))bar(x,y,done,total*2,TR("Schreibe Violyx ...","Writing Violyx ...")); } }
  d->fl(d); p=data; for(u32 i=0;i<nrec;i++){ u64 l=*(u64*)(rec+i*16); u32 c=*(u32*)(rec+i*16+8),k=*(u32*)(rec+i*16+12); for(u32 j=0;j<c;j++){ if(!k)continue; /* Nullbereiche werden teils von spaeteren Daten ueberschrieben */ if(d->rd(d,l+j,s))return -2; if(memcmp(s,p,512))return -2; p+=512; if(!(++done%256))bar(x,y,done,total*2,TR("Prüfe geschriebene Daten ...","Verifying written data ...")); } }
  return fixgpt(d); }
void app_install(void){ if(!install_available()){ dlg_msg(TR("Installieren","Install"),TR("Bitte Violyx dafür von der ISO oder dem USB-Stick starten.","Please start Violyx from the ISO or USB stick for this.")); return; } if(!blk_count()){ dlg_msg(TR("Installieren","Install"),TR("Keine unterstützte Platte gefunden.","No supported disk found.")); return; } int i=choose_disk(); if(i<0)return; blkdev*d=blk_get(i); if(!warn(d)){ dlg_msg(TR("Installieren","Install"),TR("Abgebrochen. Es wurde nichts verändert.","Cancelled. Nothing was changed.")); return; }
  char w[16]; w[0]=0; if(!dlg_input(TR("Letzte Bestätigung","Final confirmation"),TR("Zum Löschen LÖSCHEN eintippen:","Type DELETE to erase:"),w,16)||strcmp(w,TR("L\x99SCHEN","DELETE"))){ dlg_msg(TR("Installieren","Install"),TR("Abgebrochen. Es wurde nichts verändert.","Cancelled. Nothing was changed.")); return; } int r=write_all(d); if(r==-2)dlg_msg(TR("Installieren","Install"),TR("Prüfung fehlgeschlagen! Die Platte ist unvollständig beschrieben.","Verification failed! The disk is incompletely written.")); else if(r)dlg_msg(TR("Installieren","Install"),TR("Schreibfehler! Die Platte ist unvollständig beschrieben.","Write error! The disk is incompletely written.")); else { fs_attach(d); cfg_save(); } if(!r&&dlg_confirm(TR("Fertig","Done"),TR("Installiert. Medium entfernen, dann neu starten?","Installed. Remove the medium, then restart?")))reboot(); }
